// Custom Worker entry: wraps the OpenNext (Next.js) handler and adds the admin
// dashboard backend (a Durable Object) plus the 5-minute cron that retries form
// notifications and checks for replies.
// @ts-ignore `.open-next/worker.js` is generated by `npm run build`
import { default as nextHandler } from "./.open-next/worker.js";
import PostalMime, { type Address } from "postal-mime";
import type { Env } from "./worker/store";
import { stripHtml } from "./worker/util";

export { AdminStore } from "./worker/store";

const store = (env: Env) => env.ADMIN_STORE.get(env.ADMIN_STORE.idFromName("main"));
const PRIMARY_HOST = "ramjanaliakash.com";
const REDIRECT_HOSTS = new Set(["www.ramjanaliakash.com", "ramjan-ali-tracker.ramjan-ali.workers.dev"]);
const NOTIFY_EMAIL = "raakash.meet@gmail.com";

function mailbox(address?: Address) {
  if (!address || "group" in address) return { name: "", address: "" };
  return { name: address.name || "", address: address.address || "" };
}

function withAssetCache(response: Response, pathname: string, method: string) {
  if (method !== "GET" && method !== "HEAD") return response;
  const cacheable =
    pathname.startsWith("/_next/static/") || pathname === "/_next/image" || pathname.startsWith("/assets/");
  if (!cacheable || !response.ok) return response;
  const headers = new Headers(response.headers);
  headers.set("Cache-Control", "public, max-age=31536000, immutable");
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

function withPrivateRobots(response: Response) {
  const headers = new Headers(response.headers);
  headers.set("X-Robots-Tag", "noindex, nofollow, noarchive");
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    if (url.protocol !== "https:" || REDIRECT_HOSTS.has(url.hostname)) {
      url.protocol = "https:";
      if (REDIRECT_HOSTS.has(url.hostname)) url.hostname = PRIMARY_HOST;
      url.port = "";
      return Response.redirect(url.toString(), 308);
    }
    const { pathname } = url;
    if (pathname.startsWith("/api/admin/") || pathname === "/api/lead" || pathname === "/api/hooks/cal" || pathname === "/api/hooks/resend") {
      return withPrivateRobots(await store(env).fetch(request));
    }
    const response = await nextHandler.fetch(request, env, ctx);
    return withAssetCache(response, pathname, request.method);
  },
  async scheduled(_controller: ScheduledController, env: Env, ctx: ExecutionContext): Promise<void> {
    ctx.waitUntil(store(env).tick());
  },
  async email(message: ForwardableEmailMessage, env: Env, ctx: ExecutionContext): Promise<void> {
    const raw = await new Response(message.raw).arrayBuffer();
    const parsed = await PostalMime.parse(raw);
    const from = mailbox(parsed.from);
    const body = parsed.text || stripHtml(parsed.html || "") || "(empty email)";
    await store(env).ingestRoutedEmail({
      from: message.from || from.address,
      fromName: from.name,
      to: message.to,
      subject: parsed.subject || "(no subject)",
      body,
      messageId: parsed.messageId || message.headers.get("message-id") || undefined,
      inReplyTo: parsed.inReplyTo || message.headers.get("in-reply-to") || undefined,
      references: parsed.references || message.headers.get("references") || undefined,
      attachments: parsed.attachments.map((file) => ({
        filename: file.filename || "attachment",
        contentType: file.mimeType || "application/octet-stream",
        size: typeof file.content === "string" ? file.content.length : file.content.byteLength,
      })),
    });
    if (env.EMAIL) ctx.waitUntil(env.EMAIL.send({
      from: { email: "hello@ramjanaliakash.com", name: "Ramjan Ali" },
      to: [{ email: NOTIFY_EMAIL }],
      replyTo: { email: from.address || message.from, name: from.name || undefined },
      subject: `New dashboard reply: ${parsed.subject || "(no subject)"}`,
      text: `From: ${from.name ? `${from.name} <${from.address || message.from}>` : message.from}\n\n${body.slice(0, 8000)}`,
    }).catch(() => undefined));
  },
} satisfies ExportedHandler<Env>;
